    30→export const Notifications: React.FC<
    31→  NativeStackScreenProps<Routes, "notifications">
    32→> = ({ navigation }) => {
    33→  const isPermitted = useAtomValue(PushNotificationsAtoms.isPermitted);
    34→  const [enableMentions, setEnableMentions] = useState(true);
    35→  const [enableInvitations, setEnableInvitations] = useState(true);
    36→  const [groupChatLevel, setGroupChatLevel] =
    37→    useState<NotificationLevel>("all");
    38→  const [directChatLevel, setDirectChatLevel] =
    39→    useState<NotificationLevel>("all");
    40→  const [loading, setLoading] = useState(true);
    41→  const isFocused = useIsFocused();
    42→  const [hasAllowedNotificationsIntro, setHasAllowedNotificationsIntro] =
    43→    useAtom(PushNotificationsAtoms.hasAllowedNotificationsIntro);
    44→
    45→  // Load current push rule settings on mount and when screen gains focus
    46→  const loadSettings = useCallback(async () => {
    47→    try {
    48→      setLoading(true);
    49→      const settings = await PushRulesService.getNotificationSettings();
    50→
    51→      if (settings) {
    52→        setGroupChatLevel(settings.groupChats);
    53→        setDirectChatLevel(settings.directChats);
    54→        setEnableMentions(settings.mentions);
    55→        setEnableInvitations(settings.invitations);
    56→      }
    57→    } catch (error) {
    58→      console.error("Failed to load notification settings:", error);
    59→    } finally {
    60→      setLoading(false);
    61→    }
    62→  }, []);
    63→
    64→  useEffect(() => {
    65→    if (!isFocused) return;
    66→    loadSettings();
    67→  }, [isFocused, loadSettings]);
    68→
    69→  // Handle mentions toggle
    70→  const handleMentionsToggle = async () => {
    71→    const newValue = !enableMentions;
    72→    setEnableMentions(newValue);
    73→    try {
    74→      await PushRulesService.setMentionsEnabled(newValue);
    75→    } catch (error) {
    76→      console.error("Failed to update mentions setting:", error);
    77→      // Revert on error
    78→      setEnableMentions(!newValue);
    79→    }
    80→  };
    81→
    82→  // Handle invitations toggle
    83→  const handleInvitationsToggle = async () => {
    84→    const newValue = !enableInvitations;
    85→    setEnableInvitations(newValue);
    86→    try {
    87→      await PushRulesService.setInvitationsEnabled(newValue);
    88→    } catch (error) {
    89→      console.error("Failed to update invitations setting:", error);
    90→      // Revert on error
    91→      setEnableInvitations(!newValue);
    92→    }
    93→  };
    94→
    95→  // Format notification level for display
    96→  const formatLevel = (level: NotificationLevel): string => {
    97→    switch (level) {
    98→      case "all":
    99→        return "All";
   100→      case "mentions":
   101→        return "Mentions";
   102→      case "none":
   103→        return "Off";
   104→    }
   105→  };
   106→
   107→  const handleEnableNotifications = () => {
   108→    /**If the user has not allowed notifications intro and the permissions are not granted,
   109→     *  set the hasAllowedNotificationsIntro to true and the native popup will be shown becuase we handle
   110→     * the permissions request in the PushNotificationsProvider.*/
   111→    if (!hasAllowedNotificationsIntro && !isPermitted) {
   112→      setHasAllowedNotificationsIntro(true);
   113→      return;
   114→    }
   115→
   116→    Linking.openSettings();
   117→  };
   118→
   119→  return (
   120→    <ScreenLayout type="modal">
   121→      {loading && <Loading />}
   122→      <Block flex={1} align="center" gap={40}>
   123→        <GoBackHeader title="Notifications" margins={0} />
   124→        <RadioButton
   125→          checked={!!isPermitted}
   126→          onToggle={handleEnableNotifications}
   127→          label="Enable notifications"
   128→        />
   129→        {isPermitted && (
   130→          <>
   131→            <Block gap={8} width="100%">
   132→              <Text
   133→                size={TextSize.tiny}
   134→                color={Colors.white50}
   135→                paddings={[0, 12]}
   136→              >
   137→                Notification Type
   138→              </Text>
   139→              <Block
   140→                border={{ borderRadius: 16 }}
   141→                width="100%"
   142→                background={Colors.white5}
   143→              >
   144→                {NOTIFICATION_TYPES.map((item, index, array) => {
   145→                  const isGroupChat = item.title === "Group chats";
   146→                  const currentLevel = isGroupChat
   147→                    ? groupChatLevel
   148→                    : directChatLevel;
   149→
   150→                  return (
   151→                    <Button.Wrapper
   152→                      key={item.title}
   153→                      onPress={() =>
   154→                        navigation.navigate("notificationsType", {
   155→                          type: isGroupChat ? "group" : "direct",
   156→                          notificationsType: currentLevel,
   157→                        })
   158→                      }
   159→                    >
   160→                      <Block paddings={[0, 12]}>
   161→                        <Block
   162→                          flexDirection="row"
   163→                          align="center"
   164→                          justify="space-between"
   165→                          gap={12}
   166→                          paddings={[20, 0]}
   167→                          border={
   168→                            index !== array.length - 1
   169→                              ? {
   170→                                  borderBottomWidth: 1,
   171→                                  borderColor: Colors.white5,
   172→                                }
   173→                              : undefined
   174→                          }
   175→                        >
   176→                          <Text size={TextSize.base}>{item.title}</Text>
   177→                          <Block flexDirection="row" align="center" gap={8}>
   178→                            <Text size={TextSize.base} color={Colors.white50}>
   179→                              {formatLevel(currentLevel)}
   180→                            </Text>
   181→                            <Image
   182→                              source={require("assets/icons/caret-left.png")}
   183→                              style={styles.caret}
   184→                              tintColor={Colors.white50}
   185→                            />
   186→                          </Block>
   187→                        </Block>
   188→                      </Block>
   189→                    </Button.Wrapper>
   190→                  );
   191→                })}
   192→              </Block>
   193→            </Block>
   194→            <Block gap={8} width="100%">
   195→              <Text
   196→                size={TextSize.tiny}
   197→                color={Colors.white50}
   198→                paddings={[0, 12]}
   199→              >
   200→                Mentions
   201→              </Text>
   202→              <RadioButton
   203→                checked={enableMentions}
   204→                onToggle={handleMentionsToggle}
   205→                label="Enable mentions"
   206→              />
   207→            </Block>
   208→            <Block gap={8} width="100%">
   209→              <Text
   210→                size={TextSize.tiny}
   211→                color={Colors.white50}
   212→                paddings={[0, 12]}
   213→              >
   214→                Additional
   215→              </Text>
   216→              <RadioButton
   217→                checked={enableInvitations}
   218→                onToggle={handleInvitationsToggle}
   219→                label="Invitations"
   220→              />
   221→            </Block>
   222→          </>
   223→        )}
   224→      </Block>
   225→    </ScreenLayout>
   226→  );
   227→};
